	@Override
	public void renderAll(PoseStack pose, VertexConsumer vc, int light, int overlay, BlockEntity te, List<?> li, float phi, float theta) {

		pose.pushPose();
		double d = 0.9375;
		pose.translate(0, d, 0);
		pose.mulPose(TechneModel.rotation(phi, 0, 0, 1));
		pose.translate(0, -d, 0);
		double dx = -0.0625;
		pose.translate(0, 0, dx);
		double s = 1.25;
		pose.scale(1, 1, (float)s);
		Shape1.render(pose, vc, light, overlay);
		Shape1a.render(pose, vc, light, overlay);

		pose.pushPose();
		double sc = 2;
		double dz = 0.25;
		pose.translate(0, -d, dz);
		pose.scale((float)sc, (float)sc, 0.35F);
		this.renderCenter(pose, vc, light, overlay, te);
		pose.popPose();

		pose.pushPose();
		sc = 2;
		dz = -0.25;
		pose.translate(0, -d, dz);
		pose.scale((float)sc, (float)sc, 0.35F);
		this.renderCenter(pose, vc, light, overlay, te);
		pose.popPose();

		pose.pushPose();
		sc = 1.75;
		pose.translate(0, -0.6875, 0);
		pose.scale((float)sc, (float)sc, 0.35F);
		this.renderCenter(pose, vc, light, overlay, te);
		pose.popPose();
		

		
		pose.popPose();
	}

